import os
import json
import time
import uuid
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class CloudWatchLogWriter:
    def __init__(
        self,
        log_group_name: str,
        log_stream_name: str,
        region_name: Optional[str] = None,
    ) -> None:
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name
        self.client = boto3.client("logs", region_name=region_name)
        self.sequence_token: Optional[str] = None

        self._ensure_log_group()
        self._ensure_log_stream()
        self._refresh_sequence_token()

    def _ensure_log_group(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass
        except (ClientError, BotoCoreError):
            pass

    def _ensure_log_stream(self) -> None:
        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass
        except (ClientError, BotoCoreError):
            pass

    def _refresh_sequence_token(self) -> None:
        try:
            resp = self.client.describe_log_streams(
                logGroupName=self.log_group_name,
                logStreamNamePrefix=self.log_stream_name,
                limit=1,
            )
            streams = resp.get("logStreams", [])
            if streams and "uploadSequenceToken" in streams[0]:
                self.sequence_token = streams[0]["uploadSequenceToken"]
        except (ClientError, BotoCoreError):
            self.sequence_token = None

    def put_events(self, events: List[Dict[str, Any]]) -> Dict[str, Any]:
        log_events = []
        now_ms = int(time.time() * 1000)
        for event in events:
            payload = dict(event)
            payload.setdefault("timestamp", now_ms)
            log_events.append(
                {
                    "timestamp": int(payload.pop("timestamp")),
                    "message": json.dumps(payload, separators=(",", ":"), sort_keys=True),
                }
            )

        kwargs = {
            "logGroupName": self.log_group_name,
            "logStreamName": self.log_stream_name,
            "logEvents": log_events,
        }
        if self.sequence_token:
            kwargs["sequenceToken"] = self.sequence_token

        try:
            resp = self.client.put_log_events(**kwargs)
            self.sequence_token = resp.get("nextSequenceToken", self.sequence_token)
            return resp
        except self.client.exceptions.InvalidSequenceTokenException:
            self._refresh_sequence_token()
            if self.sequence_token:
                kwargs["sequenceToken"] = self.sequence_token
            else:
                kwargs.pop("sequenceToken", None)
            resp = self.client.put_log_events(**kwargs)
            self.sequence_token = resp.get("nextSequenceToken", self.sequence_token)
            return resp


def write_application_logs_with_correlation_id(
    correlation_id: str,
    message: str,
    *,
    log_group_name: Optional[str] = None,
    log_stream_name: Optional[str] = None,
    region_name: Optional[str] = None,
    level: str = "INFO",
    extra: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    log_group_name = log_group_name or os.environ.get("CLOUDWATCH_LOG_GROUP", "application-logs")
    log_stream_name = log_stream_name or os.environ.get(
        "CLOUDWATCH_LOG_STREAM", f"app-{uuid.uuid4().hex}"
    )
    region_name = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")

    writer = CloudWatchLogWriter(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )

    base_event = {
        "service": os.environ.get("SERVICE_NAME", "application"),
        "level": level,
        "message": message,
        "correlation_id": correlation_id,
        "request_id": correlation_id,
    }
    if extra:
        base_event.update(extra)

    return writer.put_events([base_event])


def write_batch_application_logs(
    correlation_id: str,
    messages: List[str],
    *,
    log_group_name: Optional[str] = None,
    log_stream_name: Optional[str] = None,
    region_name: Optional[str] = None,
    level: str = "INFO",
    extra: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    log_group_name = log_group_name or os.environ.get("CLOUDWATCH_LOG_GROUP", "application-logs")
    log_stream_name = log_stream_name or os.environ.get(
        "CLOUDWATCH_LOG_STREAM", f"app-{uuid.uuid4().hex}"
    )
    region_name = region_name or os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")

    writer = CloudWatchLogWriter(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )

    now_ms = int(time.time() * 1000)
    events: List[Dict[str, Any]] = []
    for idx, msg in enumerate(messages):
        payload = {
            "service": os.environ.get("SERVICE_NAME", "application"),
            "level": level,
            "message": msg,
            "correlation_id": correlation_id,
            "request_id": correlation_id,
            "sequence": idx,
            "timestamp": now_ms + idx,
        }
        if extra:
            payload.update(extra)
        events.append(payload)

    return writer.put_events(events)
